; stub.asm — generated by build.py. loads the first three sectors to 0000:8000 and
; jumps into the pixels. it lives in BMP palette entries 31..37, so its bytes are
; colours: instruction order and the fillers marked ; colour were chosen by search
; so those colours sit close to the ramp they replace.
bits 16
org 0x7CB5

    dec dx                
    push byte 0           
    pop es                
    mov ax, 0x0203        
    inc si                ; colour
    inc bp                ; colour
    mov bx, 0x8000        
    mov cx, 0x0001        
    inc di                ; colour
    mov dh, 0             
    int 0x13              
    jmp 0x0000:34067      
